    "swap": {
      "result": "pass",
      "reason": "The narrative depends on Iris’s reference-source calibration result, specific collaboration role, and three working documents."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The spatial sequence explains measurement offsets, calibration, and remaining residuals rather than serving only as decoration."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence moves coherently from the measurement problem through calibration to evidence and the method supporting it."
    },
    "clipart": {
      "result": "fail",
      "reason": "No central object persists through the whole scroll; the instrument disappears before the method section."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan accurately limits the result, authorship, manuscript status, and grant contribution."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies name, work, and contact, with a direct link to the prominently scoped Vela result."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening promise is understandable outside physics, and the subsequent explanation defines residuals without overstating the science."
    }
  },
